import java.util.*;
import java.util.function.*;
// Command broker, visit identity and transfer attempt are separate objects.
public class Workflow {
 public interface Environment {Object call(String method,Object... args);int bind(Consumer<Object> callback);}
 public static Map<String,Object> obj(Object... values){Map<String,Object> m=new LinkedHashMap<>();for(int i=0;i<values.length;i+=2)m.put((String)values[i],values[i+1]);return m;}
 public static class File {public final String id;public final int token,size;public final boolean feed;public File(String id,int token,int size,boolean feed){this.id=id;this.token=token;this.size=size;this.feed=feed;}}
 public static class Visit {final int id;final File file;Attempt handle;Visit(int id,File file){this.id=id;this.file=file;}}
 public static class Attempt {
  public final File file;public final int number;public boolean aborted;final Environment env;Runnable stop=()->{};
  public Attempt(Environment env,File file,int number,IntSupplier active,Consumer<Object> audit,BiConsumer<Object,Integer> view){this.env=env;this.file=file;this.number=number;env.call("transport",file.token,number);
   if(file.feed){int callback=env.bind(packet->{ final int order=active.getAsInt();
     Consumer<Object> deliver=frame->{ audit.accept(frame);view.accept(frame,order);};
     Map<?,?> value=(Map<?,?>)env.call("decode",file.token,packet,env.bind(deliver));if(!Boolean.TRUE.equals(value.get("deferred")))deliver.accept(value.get("frame"));});
    int subscription;
    env.call("start",file.token);subscription=((Number)env.call("listen",file.token,callback)).intValue();
    stop=()->env.call("unlisten",file.token,subscription);if(aborted)stop.run();}
  }
  public void cancel(){if(aborted)return;aborted=true;stop.run();env.call("cancel",file.token,number);}
 }
 static class CommandLedger {final Environment env;int number;CommandLedger(Environment env){this.env=env;}int accept(Visit v,String kind){int n=++number;Map<String,Object> entry=obj("fileId",v.file.id,"attemptId",n,"visitId",v.id,"kind",kind); env.call("record",entry);return n;}}
 public interface Client {Attempt select(File file);Attempt retry();void hide();void dispose();Map<String,Object> snapshot();}
 public static class Broker implements Client {
  final Environment env;final CommandLedger ledger;Visit visit;int serial;boolean disposed;final List<Attempt> tasks=new ArrayList<>();public Broker(Environment env){this.env=env;this.ledger=new CommandLedger(env);}
  boolean current(Visit v){return visit==v;}
  Attempt enqueue(Visit v,String kind){int n=ledger.accept(v,kind);
   Attempt h=new Attempt(env,v.file,n,()->0,frame->env.call("recordProgress",obj("fileId",v.file.id,"attemptId",n,"frame",frame)),(frame,order)->{if(current(v))env.call("showProgress",obj("fileId",v.file.id,"attemptId",n,"frame",frame));});tasks.add(h);return h;}
  void notice(Visit v,Attempt h){ env.call("showQueued",obj("fileId",v.file.id,"attemptId",h.number,"visitId",v.id,"status","queued"));}
  void release(Visit v){Attempt h=v.handle;v.handle=null;if(h!=null)h.cancel();}
  public Attempt select(File file){if(disposed)return null;int request=++serial;Visit old=visit;visit=null;if(old!=null)release(old);if(disposed||serial!=request)return null;Visit v=new Visit(request,file);visit=v;Attempt h=enqueue(v,"select");if(current(v)){v.handle=h;notice(v,h);}else h.cancel();return h;}
  public Attempt retry(){Visit v=visit;if(v==null||v.handle==null||disposed)return null;v.handle.cancel(); Visit accepted=v;Attempt h=enqueue(accepted,"retry");if(current(accepted))accepted.handle=h;else h.cancel();if(current(accepted))notice(accepted,h);return h;}
  public void hide(){serial++;Visit old=visit;visit=null;if(old!=null)release(old);}
  public void dispose(){if(disposed)return;disposed=true;hide();for(Attempt h:new ArrayList<>(tasks))h.cancel();}
  public Map<String,Object> snapshot(){Visit v=visit;return obj("visitId",v==null?null:v.id,"fileId",v==null?null:v.file.id,"attemptId",v==null||v.handle==null?null:v.handle.number,"disposed",disposed,"attempts",ledger.number);}
 }
 public static Client create(Environment env){return new Broker(env);}
 public static class Telemetry {public final Runnable stop;public Telemetry(Environment env,File file){int callback=env.bind(packet->{Consumer<Object> deliver=frame->env.call("recordDelta",frame);Map<?,?> value=(Map<?,?>)env.call("decode",file.token,packet,env.bind(deliver));if(!Boolean.TRUE.equals(value.get("deferred")))deliver.accept(value.get("frame"));});int subscription;env.call("start",file.token);subscription=((Number)env.call("listen",file.token,callback)).intValue(); stop=()->env.call("unlisten",file.token,subscription);}}
}

