import java.util.*;
import java.util.function.*;
// Command broker, visit identity and transfer attempt are separate objects.
public class Workflow {
 public interface Environment {Object call(String method,Object... args);int bind(Consumer<Object> callback);}
 public static Map<String,Object> obj(Object... values){Map<String,Object> m=new LinkedHashMap<>();for(int i=0;i<values.length;i+=2)m.put((String)values[i],values[i+1]);return m;}
 public static class File {public final String id;public final int token,size;public final boolean feed;public File(String id,int token,int size,boolean feed){this.id=id;this.token=token;this.size=size;this.feed=feed;}}
 public static class Visit {final int id;final File file;Attempt handle;int generation;Visit(int id,File file){this.id=id;this.file=file;}}
 public static class Attempt {
  public final File file;public final int number;public boolean aborted;final Environment env;Runnable stop=()->{};
  private long received,displayed;
  private Attempt(Environment env,File file,int number){this.env=env;this.file=file;this.number=number;}
  public Attempt(Environment env,File file,int number,IntSupplier active,Consumer<Object> audit,BiConsumer<Object,Integer> view){
   this(env,file,number);begin(()->true,active,audit,view);
  }
  private void begin(BooleanSupplier eligible,IntSupplier active,Consumer<Object> audit,BiConsumer<Object,Integer> view){
   env.call("transport",file.token,number);
   if(file.feed){int callback=env.bind(packet->{
     if(aborted||!eligible.getAsBoolean())return;
     final long arrival=++received;final int order=active.getAsInt();
     Consumer<Object> deliver=frame->{
      audit.accept(frame);
      if(!aborted&&eligible.getAsBoolean()&&arrival>displayed){
       displayed=arrival; // Commit before painting can synchronously reenter.
       view.accept(frame,order);
      }
     };
     Map<?,?> value=(Map<?,?>)env.call("decode",file.token,packet,env.bind(deliver));if(!Boolean.TRUE.equals(value.get("deferred")))deliver.accept(value.get("frame"));});
    int subscription=((Number)env.call("listen",file.token,callback)).intValue();
    stop=()->{stop=()->{};env.call("unlisten",file.token,subscription);};
    if(aborted)stop.run();
    env.call("start",file.token);
   }
  }
  public void cancel(){if(aborted)return;aborted=true;stop.run();env.call("cancel",file.token,number);}
 }
 static class CommandLedger {final Environment env;int number;CommandLedger(Environment env){this.env=env;}int accept(Visit v,String kind){int n=++number;Map<String,Object> entry=obj("fileId",v.file.id,"attemptId",n,"visitId",v.id,"kind",kind); env.call("record",entry);return n;}}
 public interface Client {Attempt select(File file);Attempt retry();void hide();void dispose();Map<String,Object> snapshot();}
 public static class Broker implements Client {
  final Environment env;final CommandLedger ledger;Visit visit;int serial;boolean disposed;final List<Attempt> tasks=new ArrayList<>();public Broker(Environment env){this.env=env;this.ledger=new CommandLedger(env);}
  boolean current(Visit v){return visit==v;}
  boolean owns(Visit v,Attempt h){return current(v)&&v.handle==h;}
  Attempt enqueue(Visit v,String kind,int generation){int n=ledger.accept(v,kind);
   Attempt h=new Attempt(env,v.file,n);tasks.add(h);
   // Publish ownership before startup is allowed to call back into navigation.
   if(current(v)&&v.generation==generation)v.handle=h;
   h.begin(()->owns(v,h),()->0,frame->env.call("recordProgress",obj("fileId",v.file.id,"attemptId",n,"frame",frame)),(frame,order)->env.call("showProgress",obj("fileId",v.file.id,"attemptId",n,"frame",frame)));
   return h;}
  void notice(Visit v,Attempt h){ env.call("showQueued",obj("fileId",v.file.id,"attemptId",h.number,"visitId",v.id,"status","queued"));}
  void release(Visit v){Attempt h=v.handle;v.handle=null;if(h!=null)h.cancel();}
  public Attempt select(File file){if(disposed)return null;int request=++serial;Visit old=visit;visit=null;if(old!=null)release(old);if(disposed||serial!=request)return null;Visit v=new Visit(request,file);visit=v;Attempt h=enqueue(v,"select",++v.generation);if(owns(v,h)){notice(v,h);}else h.cancel();return h;}
